"proposal": {
    "capability": "deployment.set-resources",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "shop",
        "name": "sessions",
        "uid": "uid-deployment-sessions"
    },
    "params": {
        "containers": {
            "app": {
                "limits": {
                    "memory": "1228Mi"
                }
            }
        }
    },
    "expected_effect": "The memory limit will be increased to 1228Mi, allowing the app to use more memory before being OOMKilled.",
    "rationale": "The app reached its memory limit (1Gi) before being OOMKilled, and the oom_after_long_run indicates memory usage grew over time. Increasing the limit by 25% (to 1228Mi) should prevent future OOM kills while avoiding unnecessary resource allocation.",
